
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_wi0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_wi0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.290612418452507e-02, -5.277304806200138e-02, -5.257188636355024e-02, -5.226084268698936e-02, -5.176353301035041e-02, -5.092780726031613e-02, -4.941507884853917e-02, -4.636637894720975e-02, -3.940209698715006e-02, -2.430878452821976e-02, -1.367893179159680e-02, -4.495017680382304e-02, -4.854630994103531e-02, -3.989976246789430e-02, -1.722809485776850e-02, -5.111389248235712e-04, 2.260275840644827e-04, 4.146991227567142e-06, -5.862874917740209e-10, -3.172011079523612e-14]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


